-- Стилистические уточнения пояснений (общих и к вариантам) по проверке Codex, уровень P3.
-- Источник: scripts/questions/039_explanation_style.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('explanation', 'Чем make world отличается от make при сборке из исходных кодов?', NULL, NULL, 'Установить всё собранное вместе можно командой make install-world.', 'make world собирает PostgreSQL, модули contrib и документацию; обычный make не включает последние две части.'),
        ('explanation', 'Включены ли контрольные суммы страниц в кластере, созданном пакетом Ubuntu?', NULL, NULL, 'Их можно включить позже утилитой pg_checksums.', 'При штатном создании кластера PostgreSQL 16 без дополнительных опций initdb контрольные суммы выключены; включение задают явно.'),
        ('explanation', 'В каком порядке выполняются скрипты настройки при запуске psql?', NULL, NULL, 'Каталог системного скрипта показывает pg_config --sysconfdir. По умолчанию обоих файлов нет.', 'psql сначала выполняет системный psqlrc, затем пользовательский ~/.psqlrc: личные настройки могут переопределить общие.'),
        ('explanation', 'Как перечитать конфигурацию из SQL-сеанса?', NULL, NULL, 'Из командной строки то же делают pg_ctl reload и pg_ctlcluster 16 main reload.', 'SELECT pg_reload_conf(); отправляет основному процессу текущего сервера сигнал перечитать конфигурацию.'),
        ('explanation', 'Что означает context = postmaster в pg_settings?', NULL, NULL, 'sighup — перечитать конфигурацию, superuser и user — можно менять в сеансе, internal — изменить нельзя.', 'Контекст postmaster означает, что новое значение применяется только при запуске сервера, поэтому требуется перезапуск.'),
        ('explanation', 'Сколько действует значение, установленное командой SET LOCAL?', NULL, NULL, 'Аналог в виде функции — set_config(имя, значение, true).', 'SET LOCAL действует до завершения текущей транзакции; затем локальное переопределение исчезает.'),
        ('explanation', 'Как задать work_mem = 32MB для сеанса прямо при запуске psql?', NULL, NULL, 'Второй способ — options=''-c work_mem=32MB'' в строке подключения. Команда \set задаёт переменную psql, а не параметр сервера.', 'PGOPTIONS=''-c work_mem=32MB'' передаёт серверу параметр при подключении psql и задаёт его для нового сеанса.'),
        ('explanation', 'Что означает свойство транзакций «атомарность»?', NULL, NULL, 'Остальные варианты описывают изоляцию, долговечность и согласованность.', 'Атомарность означает, что изменения транзакции фиксируются целиком либо отменяются целиком.'),
        ('explanation', 'Где размещаются разобранные запросы, состояние курсоров и место для сортировок?', NULL, NULL, 'Общая память используется для буферного кеша и структур, нужных всем процессам.', 'Разобранные запросы, состояние курсоров и память обычных сортировок хранятся в локальной памяти обслуживающего процесса. Параллельные операции могут дополнительно использовать разделяемые структуры.'),
        ('explanation', 'Когда стоит использовать менеджер пула соединений, например pgBouncer?', NULL, NULL, 'Клиенты разделяют обслуживающие процессы, это нужно учитывать, например, для подготовленных операторов.', 'Пул переиспользует серверные соединения, уменьшая затраты на частые подключения и число необходимых backend-процессов.'),
        ('explanation', 'Какой размер страницы данных обычно используется и как его изменить?', NULL, NULL, 'Собранный и запущенный кластер работает со страницами только одного размера.', 'Обычно страница имеет размер 8 КБ; другой размер выбирают при сборке PostgreSQL с помощью --with-blocksize.'),
        ('explanation', 'Сколько бит отводится на статус транзакции в clog и где хранятся эти файлы?', NULL, NULL, 'Работа со статусами идёт в общей памяти, чтобы не обращаться к диску постоянно.', 'Для статуса транзакции используются два бита; постоянное хранилище статусов находится в PGDATA/pg_xact.'),
        ('explanation', 'Что делает очистка (VACUUM) в первую очередь?', NULL, NULL, 'Заодно очистка обновляет карты видимости и свободного пространства.', 'Обычный VACUUM освобождает место, занятое ненужными версиями строк, и очищает соответствующие ссылки в индексах.'),
        ('explanation', 'Какой процесс планирует работу автоочистки и запускает рабочие процессы?', NULL, NULL, 'Рабочие процессы autovacuum worker обрабатывают таблицы отдельной базы данных.', 'autovacuum launcher выбирает базы для обслуживания и организует запуск процессов autovacuum worker.'),
        ('explanation', 'Чем VACUUM FULL отличается от обычного VACUUM?', NULL, NULL, 'Если долгая исключительная блокировка недопустима, можно рассмотреть расширение pg_repack.', 'VACUUM FULL переписывает таблицу и перестраивает индексы, возвращая место ОС; на время работы требуется ACCESS EXCLUSIVE.'),
        ('explanation', 'Какое ограничение есть у REINDEX ... CONCURRENTLY?', NULL, NULL, 'Неблокирующее перестроение дольше и может завершиться неудачно, тогда индекс перестраивают ещё раз.', 'REINDEX CONCURRENTLY нельзя выполнять внутри блока транзакции и применять к индексам системного каталога.'),
        ('explanation', 'В каком каталоге находятся файлы журнала предзаписи?', NULL, NULL, 'В pg_xact хранятся статусы транзакций (clog).', 'Сегменты журнала предзаписи находятся в PGDATA/pg_wal.'),
        ('explanation', 'Что делает контрольная точка?', NULL, NULL, 'Запись буферов распределяется по времени, чтобы сгладить нагрузку на ввод-вывод.', 'Контрольная точка обеспечивает запись буферов, грязных на её начало, и фиксирует позицию WAL, с которой достаточно начинать аварийное восстановление.'),
        ('explanation', 'Какой процесс записывает журнал на диск в асинхронном режиме?', NULL, NULL, 'В синхронном режиме журнал записывает сам обслуживающий процесс, выполняющий фиксацию.', 'Процесс walwriter периодически записывает и сбрасывает WAL на диск, в том числе обслуживая асинхронные фиксации.'),
        ('explanation', 'Какие базы данных создаются при инициализации кластера?', NULL, NULL, 'Все остальные базы создаются клонированием существующих.', 'initdb создаёт template0, template1 и postgres: два шаблона и базу для обычных подключений.'),
        ('explanation', 'Для чего нужен шаблон template0?', NULL, NULL, 'template0 не должен изменяться.', 'template0 сохраняет исходное содержимое и подходит для восстановления дампа без конфликтов с изменениями template1 и создания базы с иной кодировкой.'),
        ('explanation', 'Какая функция показывает реальный путь поиска вместе с неявными схемами?', NULL, NULL, 'current_schema() возвращает только первую схему пути. Значение параметра можно посмотреть командой SHOW search_path.', 'current_schemas(true) возвращает действующий путь поиска, включая неявно добавленные схемы.'),
        ('explanation', 'Что происходит с временной схемой pg_temp_N по окончании сеанса?', NULL, NULL, 'Обращаться к временной схеме нужно по имени pg_temp без номера.', 'При завершении сеанса временные объекты удаляются, а схема pg_temp_N остаётся и может использоваться последующими сеансами.'),
        ('explanation', 'С какого префикса начинаются имена таблиц системного каталога?', NULL, NULL, 'Собственные объекты с таким префиксом создавать не рекомендуется.', 'Имена таблиц системного каталога имеют префикс pg_, например pg_class и pg_database.'),
        ('explanation', 'Чем вывод команды \d+ отличается от \d?', NULL, NULL, 'Системные объекты в список включает модификатор S, например \dtS.', 'Модификатор + добавляет подробности об объекте; конкретный набор зависит от вида команды \d.'),
        ('explanation', 'Какие табличные пространства создаются при инициализации кластера?', NULL, NULL, 'Другие табличные пространства создаёт администратор.', 'initdb создаёт pg_default для данных баз и pg_global для общих объектов кластера.'),
        ('explanation', 'Что хранится в табличном пространстве pg_global?', NULL, NULL, 'pg_global всегда находится в PGDATA/global.', 'В pg_global находятся общие каталоги кластера, например сведения о базах данных и ролях.'),
        ('explanation', 'Что PostgreSQL создаёт в PGDATA/pg_tblspc для пользовательского табличного пространства?', NULL, NULL, 'Каталог пользовательского ТП указывается при его создании.', 'В PGDATA/pg_tblspc создаётся символическая ссылка с именем, равным OID пространства, на каталог из LOCATION.'),
        ('explanation', 'Зачем внутри каталога пользовательского ТП есть подкаталог с версией сервера?', NULL, NULL, 'Дальше внутри идут подкаталоги баз данных.', 'Каталог с версией разделяет файлы разных версий PostgreSQL, что позволяет разместить рядом старые и новые файлы при обновлении.'),
        ('explanation', 'Может ли одна база данных хранить объекты в нескольких табличных пространствах?', NULL, NULL, 'И наоборот: одно ТП может использоваться разными базами.', 'У базы есть пространство по умолчанию, но её таблицам и индексам можно явно назначить другие пространства.'),
        ('explanation', 'Где хранятся объекты системного каталога конкретной базы данных?', NULL, NULL, 'В pg_global лежат только общие для кластера объекты каталога.', 'Локальные системные каталоги базы находятся в её табличном пространстве по умолчанию.'),
        ('explanation', 'Какой сценарий типичен для табличных пространств?', NULL, NULL, 'Табличное пространство — это, по сути, указание на каталог.', 'Разные табличные пространства позволяют размещать активные данные на быстрых дисках, а редко используемые — на более медленных.'),
        ('explanation', 'Как изменить предельный размер сегмента файла данных?', NULL, NULL, 'Ограничение в 1 ГБ возникло исторически из-за файловых систем.', 'Предельный размер сегмента файла данных задаётся при сборке опцией configure --with-segsize; настройкой работающего сервера его не изменить.'),
        ('explanation', 'Какой суффикс у файлов карты свободного пространства?', NULL, NULL, 'Карта свободного пространства есть и у таблиц, и у индексов.', 'Файлы карты свободного пространства имеют суффикс _fsm, от Free Space Map.'),
        ('explanation', 'Сколько файлов обычно соответствует небольшой таблице?', NULL, NULL, 'У индекса обычно два файла: нет карты видимости.', 'Небольшая обычная таблица после создания карт обычно имеет три файла: основной слой, _fsm и _vm.'),
        ('explanation', 'Что происходит с нежурналируемой таблицей после сбоя?', NULL, NULL, 'Зато работа с такими таблицами быстрее, чем с обычными.', 'После аварии содержимое UNLOGGED-таблицы сбрасывается по слою init: определение сохраняется, данные исчезают.'),
        ('explanation', 'В какой схеме находятся toast-таблицы обычных (не временных) таблиц?', NULL, NULL, 'Для временных таблиц используется схема pg_toast_temp_N.', 'TOAST-таблицы обычных невременных таблиц размещаются в схеме pg_toast.'),
        ('explanation', 'Что показывает функция pg_table_size?', NULL, NULL, 'Размер отдельного слоя показывает pg_relation_size.', 'pg_table_size учитывает все слои таблицы и её TOAST-часть, включая индекс TOAST, но не обычные индексы самой таблицы.'),
        ('explanation', 'Какая функция показывает полный размер таблицы вместе со всеми индексами?', NULL, NULL, 'pg_indexes_size суммирует размеры индексов таблицы.', 'pg_total_relation_size складывает размер таблицы с TOAST-частью и размер её обычных индексов.'),
        ('explanation', 'Какой параметр задаёт имя экземпляра, видимое в списке процессов ОС?', NULL, NULL, 'update_process_title (включён по умолчанию) показывает в имени процесса его текущее состояние.', 'cluster_name добавляет заданное имя экземпляра к названиям серверных процессов в ОС.'),
        ('explanation', 'Что происходит с накопительной статистикой при аварийной остановке сервера?', NULL, NULL, 'При штатной остановке статистика сохраняется в PGDATA/pg_stat и считывается при запуске.', 'При аварии накопительная статистика из общей памяти теряется, поэтому после такого запуска счётчики сбрасываются.'),
        ('explanation', 'Какой из параметров выключен по умолчанию в Linux?', NULL, NULL, 'Также по умолчанию выключены track_functions и track_wal_io_timing.', 'track_io_timing по умолчанию выключен из-за возможной стоимости измерений времени ввода-вывода.'),
        ('explanation', 'За ходом какой команды позволяет следить представление pg_stat_progress_vacuum?', NULL, NULL, 'Для них есть свои представления: pg_stat_progress_analyze, _create_index, _copy.', 'pg_stat_progress_vacuum показывает ход обычного VACUUM, в том числе автоочистки; VACUUM FULL отслеживается отдельно.'),
        ('explanation', 'Какое расширение собирает статистику по выполняемым запросам?', NULL, NULL, 'pgstattuple — статистика по версиям строк, pg_buffercache — состояние буферного кеша.', 'pg_stat_statements накапливает статистику выполнения запросов: вызовы, длительность, строки и использование ресурсов.'),
        ('explanation', 'Какой параметр включает коллектор сообщений?', NULL, NULL, 'Коллектор никогда не теряет сообщения, но под большой нагрузкой может стать узким местом.', 'logging_collector = on запускает коллектор сообщений; изменение требует перезапуска сервера.'),
        ('explanation', 'Что нужно, чтобы использовать приёмники журнала csvlog и jsonlog?', NULL, NULL, 'Файлы пишутся в log_directory с именем по маске log_filename.', 'Форматы csvlog и jsonlog записывает logging collector, поэтому для них он должен быть включён.'),
        ('explanation', 'Какой параметр записывает в журнал команды, выполнявшиеся дольше заданного времени?', NULL, NULL, 'log_duration записывает время выполнения всех команд, log_statement — их текст.', 'log_min_duration_statement журналирует завершённые команды длительностью не меньше заданного порога.'),
        ('explanation', 'Какой атрибут даёт роли возможность подключаться к серверу?', NULL, NULL, 'CONNECT — это привилегия на базу данных, а не атрибут роли.', 'Атрибут LOGIN разрешает использовать роль для входа; дополнительно проверяются аутентификация и доступ к базе.'),
        ('explanation', 'Подходящая строка в pg_hba.conf найдена, но аутентификация не прошла. Что дальше?', NULL, NULL, 'Если не подошла ни одна строка, доступ тоже запрещается.', 'После неудачной аутентификации по первой подходящей записи подключение отклоняется; перехода к следующим записям нет.'),
        ('explanation', 'Как работает метод аутентификации peer?', NULL, NULL, 'Можно задать и другие соответствия имён через pg_ident.conf.', 'Метод peer получает от ОС имя пользователя локального клиента и сопоставляет его с ролью напрямую или через карту имён.'),
        ('explanation', 'Что разрешает привилегия USAGE на схему?', NULL, NULL, 'Создание объектов разрешает привилегия CREATE.', 'USAGE позволяет разрешать имена объектов в схеме; права на сами объекты выдаются отдельно.'),
        ('explanation', 'С какими правами выполняется функция, объявленная как SECURITY DEFINER?', NULL, NULL, 'По умолчанию используется SECURITY INVOKER — права вызывающего.', 'Функция SECURITY DEFINER выполняется с правами владельца, что позволяет предоставить ограниченный доступ к действиям через её код.'),
        ('explanation', 'Какое преимущество у логической резервной копии?', NULL, NULL, 'Минусы — невысокая скорость и восстановление только на момент копирования.', 'Логическая копия описывает объекты и данные на уровне SQL, поэтому для восстановления не нужна двоичная совместимость файлов кластера.'),
        ('explanation', 'Какой утилитой восстанавливают копию pg_dump в специальном формате с оглавлением?', NULL, NULL, 'SQL-скрипт pg_dump восстанавливают через psql.', 'Архив pg_dump в формате custom, directory или tar читает pg_restore; оглавление позволяет выбирать восстанавливаемые объекты.'),
        ('explanation', 'Что дополнительно сохраняет pg_dumpall по сравнению с pg_dump?', NULL, NULL, 'pg_dumpall выдаёт только SQL-скрипт и не поддерживает параллельную выгрузку.', 'pg_dumpall выгружает базы кластера и глобальные объекты, включая роли и табличные пространства. Результат — SQL-скрипт; параллельная выгрузка не поддерживается.'),
        ('explanation', 'Какое ограничение у физической резервной копии?', NULL, NULL, 'Зато восстановление быстрое и возможно на произвольный момент при наличии архива WAL.', 'Физическая копия содержит файлы всего кластера и требует совместимой архитектуры и той же основной версии PostgreSQL.'),
        ('explanation', 'Как pg_basebackup подключается к серверу?', NULL, NULL, 'Нужны атрибут REPLICATION у роли, разрешение в pg_hba.conf и достаточный max_wal_senders.', 'pg_basebackup подключается по протоколу репликации. Нужны роль с REPLICATION либо суперпользователь, разрешение в pg_hba.conf и достаточный max_wal_senders; поток WAL требует дополнительного соединения.'),
        ('explanation', 'Какой процесс на реплике применяет полученные журнальные записи?', NULL, NULL, 'walreceiver получает поток WAL от процесса walsender на мастере.', 'Процесс startup воспроизводит WAL при восстановлении, в том числе на физической реплике; walreceiver только получает поток.'),
        ('explanation', 'Что будет при hot_standby = off на реплике?', NULL, NULL, 'По умолчанию hot_standby = on, и подключения для чтения разрешены.', 'При hot_standby = off реплика продолжает восстановление по WAL, но не принимает обычные подключения для запросов.'),
        ('explanation', 'Реплицируются ли команды DDL?', NULL, NULL, 'Зато возможна начальная синхронизация данных таблиц при создании подписки.', 'Встроенная логическая репликация не переносит определения таблиц и изменения схемы; совместимую структуру на подписчике готовят отдельно.'),
        ('explanation', 'Что из перечисленного не реплицируется логической репликацией?', NULL, NULL, 'Конфликтов ключей избегают разными диапазонами последовательностей или UUID.', 'Логическая репликация переносит значения столбцов строк, но не состояние генераторов SEQUENCE; его нужно синхронизировать отдельно.'),
        ('explanation', 'Как по умолчанию идентифицируется строка при репликации UPDATE и DELETE?', NULL, NULL, 'Можно задать уникальный индекс или все столбцы через REPLICA IDENTITY.', 'При REPLICA IDENTITY DEFAULT старая строка для UPDATE и DELETE идентифицируется по первичному ключу, если он есть.'),
        ('explanation', 'Какой процесс на подписчике применяет полученные изменения?', NULL, NULL, 'На публикующем сервере изменения отправляет процесс walsender.', 'На подписчике изменения получает и применяет logical replication worker, работающий с локальными таблицами.'),
        ('explanation', 'Когда публикация по умолчанию передаёт изменения подписчику?', NULL, NULL, 'Для долгих транзакций помогает параметр подписки streaming.', 'При streaming = off изменения транзакции передаются после её фиксации; streaming позволяет передавать части незавершённых транзакций.'),
        ('explanation', 'Чем опасен неактивный слот логической репликации?', NULL, NULL, 'Поэтому соединение между серверами должно быть стабильным.', 'Неактивный логический слот может удерживать WAL и версии системного каталога, необходимые для продолжения декодирования, вызывая рост занимаемого места.'),
        ('explanation', 'Что верно для утилиты initdb?', NULL, NULL, 'Сервер после initdb запускают отдельно, например pg_ctl start. Каталог кластера не может принадлежать root.', 'initdb создаёт начальные конфигурационные файлы в каталоге кластера; -U задаёт имя начальной роли-суперпользователя.'),
        ('explanation', 'Какими способами можно выполнить SQL-команды из файла?', NULL, NULL, 'Команда \o и ключ -o, наоборот, направляют вывод результатов в файл. Ещё один способ — psql < файл.', 'psql -f файл исполняет файл при запуске, а \i файл — в уже открытом сеансе.'),
        ('explanation', 'Какими способами можно перечитать файлы конфигурации?', NULL, NULL, 'В Ubuntu есть ещё pg_ctlcluster 16 main reload. RESET ALL только сбрасывает параметры сеанса.', 'pg_reload_conf() и pg_ctl reload посылают серверу SIGHUP для перечитывания конфигурации.'),
        ('explanation', 'Какими способами можно узнать текущее значение параметра work_mem в сеансе?', NULL, NULL, 'pg_file_settings показывает содержимое файлов конфигурации, а \set задаёт переменную psql. Действующие значения есть в pg_settings.', 'SHOW work_mem и current_setting(''work_mem'') возвращают действующее значение параметра в текущем сеансе.'),
        ('explanation', 'Что хранится в локальной памяти обслуживающего процесса?', NULL, NULL, 'Буферный кеш и буферы clog находятся в общей памяти, доступной всем процессам.', 'Кеш системного каталога и состояние курсоров принадлежат конкретному backend-процессу и хранятся в его локальной памяти.'),
        ('explanation', 'Допишите команду, чтобы отменить все изменения транзакции:
```
BEGIN;
UPDATE accounts SET amount = amount - 100 WHERE id = 1;
___;
```', NULL, NULL, 'END — синоним COMMIT, он фиксирует изменения.', 'ROLLBACK отменяет изменения текущей транзакции; в примере изменение accounts не будет зафиксировано.'),
        ('explanation', 'На каких уровнях изоляции транзакция может завершиться ошибкой сериализации при обычных изменениях строк (без перемещения строк между секциями)?', NULL, NULL, 'Приложение должно уметь повторять такие транзакции.', 'Repeatable Read может отвергнуть изменение строки, изменённой после снимка; Serializable дополнительно обнаруживает зависимости, нарушающие сериализуемость. После ошибки сериализации приложение должно повторить всю транзакцию с начала.'),
        ('explanation', 'Какие задачи выполняет процесс автоочистки?', NULL, NULL, 'Автоочистка также обновляет карты видимости и свободного пространства и выполняет заморозку. Файлы она не сжимает: в лучшем случае отрезает пустые страницы в конце таблицы.', 'Автоочистка выполняет VACUUM и ANALYZE: удаляет ненужные версии строк, обновляет карты свободного пространства и видимости, выполняет заморозку и собирает статистику планировщика.'),
        ('explanation', 'Что может привести к разрастанию таблиц и индексов?', NULL, NULL, 'Также разрастание вызывает неправильная настройка автоочистки.', 'Долгая транзакция может мешать удалению старых версий, а массовые изменения быстро создают много таких версий.'),
        ('explanation', 'Что верно для команды VACUUM FULL?', NULL, NULL, 'Без долгой блокировки таблицу можно перестроить сторонним расширением pg_repack.', 'VACUUM FULL переписывает таблицу компактно и требует исключительной блокировки на время перестроения.'),
        ('explanation', 'Допишите команду, чтобы перестроить индекс без блокировки изменений таблицы:
```
REINDEX INDEX ___ accounts_pkey;
```', NULL, NULL, 'REINDEX CONCURRENTLY не выполняется внутри транзакции и не работает для системных индексов.', 'CONCURRENTLY позволяет перестроить индекс без блокирования обычных изменений таблицы. REINDEX CONCURRENTLY нельзя выполнять внутри блока транзакции и применять к индексам системных каталогов.'),
        ('explanation', 'Что защищает журнал предзаписи?', NULL, NULL, 'Временные и нежурналируемые таблицы в журнал не попадают и после сбоя не восстанавливаются.', 'WAL защищает изменения обычных таблиц и индексов, а также статусы транзакций, необходимые для восстановления согласованного состояния.'),
        ('explanation', 'Какие процессы записывают грязные буферы из буферного кеша на диск?', NULL, NULL, 'walwriter пишет журнал. Если вытесняемый буфер грязный, его может записать и обслуживающий процесс.', 'bgwriter заранее записывает кандидатов на вытеснение, а checkpointer обеспечивает запись для контрольной точки. При вытеснении грязного буфера его может записать и обслуживающий процесс.'),
        ('explanation', 'Что верно для временных таблиц?', NULL, NULL, 'Страницы временных таблиц обрабатываются в локальной памяти обслуживающего процесса.', 'Временная таблица принадлежит одному сеансу, её данные не журналируются и исчезают по окончании сеанса.'),
        ('explanation', 'Что верно для типа данных oid?', NULL, NULL, 'Для преобразования имён в oid и обратно служат типы reg*, например regclass.', 'oid — 32-битный идентификатор; он используется как ключ во многих таблицах системного каталога.'),
        ('explanation', 'Где на диске находятся стандартные табличные пространства?', NULL, NULL, 'Для пользовательских табличных пространств в PGDATA/pg_tblspc создаются символические ссылки на их каталоги.', 'pg_default размещается в PGDATA/base, а pg_global — в PGDATA/global.'),
        ('explanation', 'Какие функции учитывают размер toast-части таблицы?', NULL, NULL, 'pg_relation_size показывает размер одного слоя, pg_indexes_size — только индексов таблицы.', 'pg_table_size включает TOAST-часть таблицы; pg_total_relation_size включает её и обычные индексы таблицы.'),
        ('explanation', 'Допишите команду, чтобы создать таблицу, изменения которой не пишутся в журнал предзаписи и которая видна всем сеансам:
```
CREATE ___ TABLE t (id int);
```', NULL, NULL, 'После сбоя нежурналируемая таблица становится пустой.', 'UNLOGGED создаёт таблицу без журналирования её данных, доступную разным сеансам при наличии прав. После аварии или нештатной остановки её содержимое очищается, а определение сохраняется.'),
        ('explanation', 'Допишите команду, чтобы длинные значения выносились в TOAST без сжатия:
```
ALTER TABLE t ALTER COLUMN body SET STORAGE ___;
```', NULL, NULL, 'extended — сжатие и вынос, main — сжатие без выноса по возможности, plain — без TOAST.', 'Стратегия EXTERNAL разрешает вынос длинных значений в TOAST, но запрещает их сжатие.'),
        ('explanation', 'Какие утилиты создают логическую резервную копию?', NULL, NULL, 'pg_basebackup делает физическую копию, pg_receivewal архивирует журнал.', 'pg_dump создаёт логическую копию базы, а pg_dumpall выгружает базы и глобальные объекты всего кластера.'),
        ('explanation', 'Что нужно, чтобы pg_basebackup мог подключиться по протоколу репликации?', NULL, NULL, 'Ещё нужны разрешение в pg_hba.conf и достаточное значение max_wal_senders. Настройки по умолчанию это допускают для локального подключения.', 'Для pg_basebackup нужен wal_level не ниже replica и роль с REPLICATION либо суперпользователь; отдельно настраиваются pg_hba.conf и число walsender.'),
        ('explanation', 'Что нужно, чтобы восстановить сервер из базовой копии с архивом журналов и затем запустить его как обычный, а не как реплику?', NULL, NULL, 'При необходимости задают и целевую точку восстановления. standby.signal запускает сервер в режиме реплики.', 'recovery.signal включает архивное восстановление, а restore_command задаёт получение требуемых файлов WAL из архива.'),
        ('explanation', 'Допишите команду, чтобы выгрузить только глобальные объекты кластера (роли, табличные пространства):
```
pg_dumpall ___ > globals.sql
```', NULL, NULL, '--roles-only выгружает только роли, без табличных пространств.', '--globals-only выгружает общие объекты кластера, включая роли и табличные пространства, без содержимого отдельных баз.'),
        ('explanation', 'Какие процессы участвуют в потоковой физической репликации?', NULL, NULL, 'Полученные записи на реплике применяет процесс startup.', 'walsender отправляет WAL, walreceiver принимает поток на реплике и записывает его, а startup применяет полученные записи.'),
        ('explanation', 'Что верно для каскадной репликации?', NULL, NULL, 'Синхронной может быть только реплика, подключённая к основному серверу напрямую.', 'В каскаде downstream-реплики получают WAL от промежуточных узлов, разгружая основной сервер; hot_standby_feedback передаётся вверх по цепочке.'),
        ('explanation', 'Что не передаётся логической репликацией?', NULL, NULL, 'Также не реплицируются большие объекты, представления и внешние таблицы.', 'Логическая репликация не переносит DDL, состояние последовательностей и большие объекты. Представления, материализованные представления и внешние таблицы нельзя включать в публикацию как реплицируемые таблицы.'),
        ('explanation', 'Чем логическая репликация отличается от физической?', NULL, NULL, 'Подписчик работает в обычном режиме и может изменять данные.', 'Логическая репликация выбирает отдельные таблицы и передаёт изменения строк, поэтому не требует совместимости файлов кластера.'),
        ('explanation', 'Какими способами можно идентифицировать строки при логической репликации UPDATE и DELETE?', NULL, NULL, 'Ещё можно указать уникальный индекс с ограничением NOT NULL.', 'REPLICA IDENTITY DEFAULT использует первичный ключ, если он есть; FULL — всю старую строку. Через USING INDEX можно назначить подходящий уникальный индекс по столбцам NOT NULL.'),
        ('explanation', 'Допишите команду, чтобы строки таблицы идентифицировались по всем столбцам:
```
ALTER TABLE accounts REPLICA IDENTITY ___;
```', NULL, NULL, 'DEFAULT — по первичному ключу, USING INDEX — по уникальному индексу, NOTHING — без идентификации.', 'REPLICA IDENTITY FULL использует все столбцы старой строки для её идентификации при репликации изменений.'),
        ('explanation', 'Какой каталог установки использует configure по умолчанию при сборке из исходных кодов?', NULL, NULL, 'Обычно каталог установки доступен для записи только суперпользователю ОС, поэтому в демонстрации курса задают свой через --prefix.', 'Без --prefix установка из исходных кодов использует /usr/local/pgsql; опция --prefix задаёт другой корень установки.'),
        ('explanation', 'Сервер собран командами make и make install. Как собрать и установить расширения из contrib?', NULL, NULL, 'Если собирать make world, всё вместе устанавливается командой make install-world.', 'После установки сервера модули можно собрать командой make и установить make install в подкаталоге contrib.'),
        ('explanation', 'Для чего нужна библиотека readline?', NULL, NULL, 'Это одна из библиотек, которые используются по умолчанию, но могут быть отключены при сборке.', 'Readline обеспечивает в psql редактирование командной строки, историю и автодополнение.'),
        ('explanation', 'Почему для сборки из репозитория git нужны Flex и Bison, а для сборки из архива с исходными кодами нет?', NULL, NULL, 'Поэтому сборка из git требует более широкого набора инструментов.', 'Релизный архив содержит сгенерированные C-файлы анализаторов; при сборке из Git их создают Flex и Bison.'),
        ('explanation', 'Какая утилита показывает параметры, с которыми был собран PostgreSQL?', NULL, NULL, 'Также pg_config --sysconfdir показывает каталог системного скрипта psqlrc.', 'pg_config --configure показывает параметры configure, использованные при сборке установленного PostgreSQL.'),
        ('explanation', 'Что верно для PostgreSQL как сервиса у облачного провайдера (DBaaS)?', NULL, NULL, 'Особенности конкретных облачных решений нужно изучать в документации провайдера.', 'В DBaaS провайдер обслуживает инфраструктуру и часть задач СУБД, а пользователь управляет базой через предоставленные интерфейсы и ограничения.'),
        ('explanation', 'Допишите команду, чтобы собранный сервер по умолчанию использовал порт 5555:
```
./configure --prefix=/home/student/pgsql16 ___=5555
```', NULL, NULL, 'Порт по умолчанию — 5432, в демонстрации курса его меняют, чтобы не пересечься с установленным пакетом.', '--with-pgport=5555 задаёт при сборке порт по умолчанию для сервера и клиентских программ.'),
        ('explanation', 'Что переключает команда \t?', NULL, NULL, 'Вместе \t и \a удобны для вывода, пригодного для скриптов.', '\t переключает вывод только строк результата, скрывая или возвращая заголовки и итоговую строку.'),
        ('explanation', 'Допишите команду, чтобы задать переменную окружения ОС прямо из psql:
```
\___ HELLO Hello
```', NULL, NULL, 'Проверить можно командой \! echo $HELLO.', '\setenv HELLO Hello устанавливает переменную окружения процесса psql, которую наследуют запускаемые им команды.'),
        ('explanation', 'Допишите команду, чтобы записать значение переменной окружения USER в переменную psql User:
```
\___ User USER
```', NULL, NULL, 'Подставить значение затем можно как :User.', '\getenv User USER копирует значение переменной окружения USER в переменную psql User.'),
        ('explanation', 'Допишите команду, чтобы вывести TRUE или FALSE в зависимости от того, определена ли переменная psql working_dir:
```
\echo :___
```', NULL, NULL, 'Эту проверку используют в условных конструкциях \if ... \else ... \endif.', ':{?working_dir} возвращает TRUE, если переменная psql определена, иначе FALSE.'),
        ('explanation', 'Какую переменную окружения проверяет psql, чтобы выбрать программу постраничного просмотра только для себя, не меняя её для других программ?', NULL, NULL, 'Её удобно задать в ~/.psqlrc командой \setenv, например less -XS.', 'psql сначала проверяет PSQL_PAGER, а при её отсутствии — общую переменную PAGER.'),
        ('explanation', 'Какая переменная psql задаёт приглашение для второй и следующих строк запроса?', NULL, NULL, 'У PROMPT1 и PROMPT2 одинаковое значение по умолчанию, но их можно задать по-разному.', 'PROMPT2 используется при продолжении незавершённой команды на следующей строке.'),
        ('explanation', 'Какие команды psql меняют формат вывода результатов запросов?', NULL, NULL, 'Формат с выравниванием используется по умолчанию.', '\pset задаёт форматирование, \x переключает расширенный вывод, \a — выравнивание.'),
        ('explanation', 'Как psql по умолчанию выполняет команды SQL с точки зрения транзакций?', NULL, NULL, 'После BEGIN в приглашении появляется звёздочка: транзакция активна.', 'По умолчанию AUTOCOMMIT включён: при обычном вводе команд по отдельности вне явного блока каждая успешная команда фиксируется автоматически. Несколько SQL-команд в одном аргументе psql -c обычно выполняются одной транзакцией.'),
        ('explanation', 'Какая директива postgresql.conf подключает файлы конфигурации (с окончанием .conf) из указанного каталога?', NULL, NULL, 'Обычно директивы подключения располагаются в конце postgresql.conf.', 'include_dir читает подходящие файлы .conf из указанного каталога в порядке имён.'),
        ('explanation', 'Что показывает столбец boot_val в представлении pg_settings?', NULL, NULL, 'В демонстрации курса boot_val параметра work_mem равен 4096 kB.', 'boot_val содержит встроенное значение параметра по умолчанию; оно может отличаться от текущего значения и reset_val.'),
        ('explanation', 'Допишите команду, чтобы удалить строку параметра work_mem из postgresql.auto.conf:
```
ALTER SYSTEM ___ work_mem;
```', NULL, NULL, 'После этого конфигурацию нужно перечитать, чтобы восстановилось значение из других файлов.', 'ALTER SYSTEM RESET work_mem удаляет запись work_mem из postgresql.auto.conf; для применения результата требуется перечитывание конфигурации.'),
        ('explanation', 'Допишите команду psql, чтобы посмотреть текущее значение параметра work_mem:
```
\___ work_mem
```', NULL, NULL, 'Те же значения дают SHOW, current_setting() и запрос к pg_settings.', '\dconfig work_mem показывает текущую настройку work_mem через представление параметров сервера.'),
        ('explanation', 'Что верно для пользовательских параметров вида myapp.currency_code?', NULL, NULL, 'Такие параметры удобны как переменные сеанса.', 'Параметры вида myapp.currency_code можно задавать через SET/set_config в сеансе либо в конфигурационных файлах для новых сеансов.'),
        ('explanation', 'Что означает context = sighup в pg_settings?', NULL, NULL, 'Значение user означает, что любой пользователь может изменить параметр для своего сеанса.', 'sighup означает, что изменение в конфигурационном файле можно применить перечитыванием конфигурации без перезапуска сервера.'),
        ('explanation', 'Что означает свойство транзакций «согласованность»?', NULL, NULL, 'Вместе свойства обозначаются ACID.', 'Согласованность означает, что транзакция переводит базу из одного состояния, удовлетворяющего установленным ограничениям, в другое такое состояние.'),
        ('explanation', 'Что делает этап переписывания запроса?', NULL, NULL, 'Порядок этапов: разбор, переписывание, планирование, выполнение.', 'На этапе переписывания применяются правила: например, обращение к представлению заменяется его определяющим запросом.'),
        ('explanation', 'Где хранится системный каталог — описание объектов базы данных?', NULL, NULL, 'Системный каталог нужен уже на этапе разбора запроса.', 'Системный каталог хранит описание объектов в специальных таблицах самой базы данных и читается обычными SQL-запросами.'),
        ('explanation', 'Что делает postmaster, если какой-нибудь процесс сервера завершился аварийно?', NULL, NULL, 'postmaster запускает все остальные процессы сервера.', 'postmaster отслеживает дочерние процессы; при аварии, угрожающей общей памяти, он завершает остальные процессы и инициирует восстановление при restart_after_crash = on.'),
        ('explanation', 'Какие типы индексов входят в стандартную поставку PostgreSQL?', NULL, NULL, 'Также стандартные: хеш-индексы, SP-GiST и GIN; новые типы добавляют расширения.', 'B-tree, BRIN и GiST входят в стандартные методы индексации PostgreSQL 16; LSM-дерево в эту поставку не входит.'),
        ('explanation', 'Какие языки программирования для подпрограмм входят в стандартную поставку PostgreSQL?', NULL, NULL, 'Помимо них стандартные — SQL и PL/Tcl; другие языки добавляют расширения.', 'PL/pgSQL, PL/Perl и PL/Python поставляются с PostgreSQL; для последних двух нужна соответствующая поддержка сборки. PL/Java — сторонний проект.'),
        ('explanation', 'В каком режиме клиент-серверного протокола клиент может подготовить запрос средствами самого протокола, без команды SQL PREPARE?', NULL, NULL, 'Простой режим удобен для небольших выборок.', 'Расширенный протокол разделяет Parse, Bind и Execute, позволяя подготовить запрос и затем передавать параметры без SQL-команды PREPARE.'),
        ('explanation', 'Что нужно учитывать приложению, работающему через менеджер пула соединений?', NULL, NULL, 'Пул полезен, когда клиентов много или соединения открываются и закрываются слишком часто.', 'При повторном использовании серверных соединений нельзя без проверки режима пула полагаться на закрепление клиента за одним backend и сохранность его сеансового состояния.'),
        ('explanation', 'Допишите команду, чтобы подготовить оператор с параметром:
```
___ q(int) AS SELECT * FROM t WHERE id = $1;
```', NULL, NULL, 'Подготовленные операторы также защищают от внедрения SQL-кода.', 'PREPARE q(int) AS ... создаёт подготовленный оператор с параметром; затем его выполняют через EXECUTE.'),
        ('explanation', 'Что должно уметь приложение, работающее на уровне изоляции Serializable?', NULL, NULL, 'Зато операторы можно писать так, как будто транзакция работает одна.', 'Serializable может отменить транзакцию с ошибкой сериализации; приложение должно повторить всю транзакцию с начала.'),
        ('explanation', 'Чем помечается версия строки при её создании?', NULL, NULL, 'При удалении версия помечается номером удалившей транзакции, UPDATE — это DELETE и INSERT.', 'При создании версии строки в xmin записывается идентификатор создавшей её транзакции.'),
        ('explanation', 'Обычная блокировка строки или таблицы была получена после установки точки сохранения. Когда она будет снята при откате к этой точке?', NULL, NULL, 'В остальных случаях блокировки снимаются при завершении транзакции.', 'Откат к точке сохранения сразу освобождает обычные блокировки, полученные после её установки.'),
        ('explanation', 'Допишите команду, чтобы узнать уровень изоляции текущей транзакции:
```
SHOW ___;
```', NULL, NULL, 'Уровень по умолчанию для новых транзакций задаёт default_transaction_isolation.', 'SHOW transaction_isolation показывает уровень изоляции текущей транзакции.'),
        ('explanation', 'Допишите команду, чтобы все новые транзакции сеанса по умолчанию работали на уровне Repeatable Read:
```
SET ___ = ''repeatable read'';
```', NULL, NULL, 'По умолчанию используется Read Committed.', 'default_transaction_isolation задаёт уровень, с которым будут начинаться новые транзакции этого сеанса.'),
        ('explanation', 'Для чего служит карта свободного пространства таблицы?', NULL, NULL, 'Для ускорения поиска карта имеет древовидную структуру.', 'Карта свободного пространства помогает найти страницу таблицы с достаточным свободным местом для новой версии строки.'),
        ('explanation', 'Как карта видимости ускоряет доступ только по индексу?', NULL, NULL, 'Если карту не обновлять, индексный доступ работает менее эффективно.', 'Если страница отмечена all-visible, индексному сканированию не нужно обращаться к таблице для проверки видимости найденной версии.'),
        ('explanation', 'Как PostgreSQL собирает статистику для планировщика?', NULL, NULL, 'Достаточно, чтобы статистика периодически обновлялась и не слишком отличалась от действительности.', 'ANALYZE оценивает распределение значений по случайной выборке строк, что ограничивает стоимость анализа больших таблиц.'),
        ('explanation', 'Что отмечает дополнительный бит в карте видимости?', NULL, NULL, 'Основной бит отмечает страницы, где все версии видны во всех снимках.', 'Дополнительный бит all-frozen отмечает страницы, на которых все версии заморожены и повторная заморозка пока не нужна.'),
        ('explanation', 'Чем автоочистка лучше очистки по расписанию?', NULL, NULL, 'Автоочистка должна работать, но требует настройки.', 'Автоочистка запускает обработку с учётом накопленных изменений, поэтому активные таблицы обслуживаются чаще, чем редко меняющиеся.'),
        ('explanation', 'Что блокирует команда REINDEX?', NULL, NULL, 'Неблокирующий вариант выполняется дольше и может завершиться неудачно.', 'Обычный REINDEX блокирует запись в таблицу и доступ к индексу; планирование запросов может ждать даже без последующего использования этого индекса.'),
        ('explanation', 'Какое стороннее расширение позволяет перестроить таблицу и её индексы без долгой исключительной блокировки?', NULL, NULL, 'VACUUM FULL тоже перестраивает таблицу, но требует исключительной блокировки.', 'pg_repack — стороннее расширение для перестроения таблиц и индексов с сокращением времени исключительной блокировки.'),
        ('explanation', 'Допишите запрос, чтобы узнать суммарный размер индексов таблицы t:
```
SELECT ___(''t'');
```', NULL, NULL, 'В практике курса так следят за разрастанием таблицы и индекса.', 'pg_indexes_size(''t'') возвращает суммарный размер индексов таблицы t.'),
        ('explanation', 'Допишите команду из практики курса, чтобы выключить автоочистку (затем конфигурацию нужно перечитать):
```
ALTER SYSTEM SET autovacuum = ___;
```', NULL, NULL, 'Вернуть значение по умолчанию можно командой ALTER SYSTEM RESET autovacuum.', 'off выключает обычную автоочистку после применения конфигурации; защитные запуски против переполнения XID сохраняются.'),
        ('explanation', 'Что хранит буфер в буферном кеше, кроме самой страницы данных?', NULL, NULL, 'Размер страницы обычно 8 Кбайт и меняется только при сборке.', 'Дескриптор буфера содержит идентификатор страницы и служебное состояние, включая признак изменения, счётчик использования и закрепления.'),
        ('explanation', 'Почему обращение к буферному кешу медленнее простого обращения к оперативной памяти?', NULL, NULL, 'Поэтому чем меньше данных читает и меняет запрос, тем быстрее он работает.', 'Доступ к общему буферному кешу требует координации процессов и блокировок, поэтому дороже простого обращения к локальной памяти.'),
        ('explanation', 'Почему изменённая страница записывается на диск не сразу?', NULL, NULL, 'Такой буфер называют грязным.', 'Отложенная запись позволяет объединять изменения страницы и уменьшать ввод-вывод; восстановление до записи страницы обеспечивает WAL.'),
        ('explanation', 'Процессу нужна страница, которой нет в буферном кеше. Что он делает?', NULL, NULL, 'Если места в кеше нет, сначала вытесняется давно не использовавшаяся страница.', 'Backend получает свободный буфер и читает страницу через ОС; чтение может обслужить кеш ОС без обращения к накопителю.'),
        ('explanation', 'Почему запись через журнал эффективнее, чем запись каждой изменённой страницы сразу на диск?', NULL, NULL, 'На эффективность можно влиять, выбирая синхронный или асинхронный режим.', 'Журнал обычно содержит компактные записи и пишется последовательно; страницы данных можно записать позже, объединив несколько изменений.'),
        ('explanation', 'Какой системный вызов (или его вариант) PostgreSQL использует, чтобы журнальная запись не осталась в кеше ОС?', NULL, NULL, 'Пока идёт такая запись, процесс, выполняющий фиксацию, вынужден ждать.', 'fsync или выбранный через wal_sync_method эквивалент требует сбросить WAL из кеша ОС на устойчивое хранилище.'),
        ('explanation', 'Чем рискует асинхронный режим фиксации?', NULL, NULL, 'На практике оба режима работают совместно.', 'Асинхронная фиксация подтверждается до надёжного сброса WAL; при сбое возможна потеря последних подтверждённых транзакций без нарушения согласованности восстановленной базы.'),
        ('explanation', 'Страница данных сбрасывается на диск, а соответствующая ей журнальная запись ещё не записана. Что произойдёт?', NULL, NULL, 'Поэтому синхронный и асинхронный режимы записи журнала работают совместно.', 'Перед сбросом страницы сервер синхронно сбрасывает WAL как минимум до LSN этой страницы, соблюдая правило write-ahead.'),
        ('explanation', 'Какие обычные транзакции после восстановления после сбоя считаются оборванными?', NULL, NULL, 'Восстановление начинается с последней завершённой контрольной точки.', 'Обычная транзакция без устойчивой записи COMMIT после аварии считается незавершённой, и её изменения не видны как зафиксированные.'),
        ('explanation', 'Когда контрольная точка считается выполненной?', NULL, NULL, 'Контрольная точка сбрасывает и буферы clog со статусами транзакций.', 'Контрольная точка завершается после надёжной записи требуемых данных и служебного состояния, включая буферы, грязные на её начало.'),
        ('explanation', 'Что добавляет в журнал уровень replica по сравнению с minimal?', NULL, NULL, 'Уровень replica используется по умолчанию.', 'Уровень replica журналирует изменения, необходимые для восстановления из базовой копии и физической репликации; minimal может пропускать некоторые массовые изменения.'),
        ('explanation', 'Допишите команду, чтобы журнал позволял настроить логическую репликацию (после неё нужен перезапуск сервера):
```
ALTER SYSTEM SET wal_level = ___;
```', NULL, NULL, 'Параметр wal_level меняется только с перезапуском сервера.', 'logical добавляет сведения для декодирования изменений строк; изменение wal_level применяется после перезапуска.'),
        ('explanation', 'Что делает сервер при остановке в режиме fast?', NULL, NULL, 'В Ubuntu такую остановку выполняет pg_ctlcluster 16 main stop.', 'Режим fast отключает клиентов, отменяет активные транзакции и выполняет штатную остановку с контрольной точкой.'),
        ('explanation', 'Сервер был остановлен в режиме immediate. Что произойдёт при следующем запуске?', NULL, NULL, 'В журнале сообщений это видно как восстановление после сбоя.', 'После immediate сервер при запуске воспроизводит WAL, чтобы восстановить согласованное состояние файлов данных.'),
        ('explanation', 'Какие схемы обычно есть в каждой базе данных?', NULL, NULL, 'Кроме них есть технические схемы, например временные pg_temp_N.', 'В обычной новой базе есть public, pg_catalog и information_schema; pg_default является табличным пространством.'),
        ('explanation', 'Как обратиться к временной схеме текущего сеанса, не зная её номера?', NULL, NULL, 'Временная схема создаётся автоматически при создании первой временной таблицы.', 'Имя pg_temp обозначает временную схему текущего сеанса независимо от её числового суффикса.'),
        ('explanation', 'Если pg_temp не указана в search_path, где она подразумевается при поиске таблиц?', NULL, NULL, 'Обе схемы можно указать в пути явно на нужном месте.', 'При поиске таблиц существующая временная схема, не указанная явно, проверяется первой, даже раньше pg_catalog.'),
        ('explanation', 'Допишите команду, чтобы создать таблицу, которая существует только в текущем сеансе:
```
CREATE ___ TABLE t (id int);
```', NULL, NULL, 'Можно также ограничить время жизни таблицы транзакцией.', 'CREATE TEMP TABLE создаёт таблицу только для текущего сеанса; по умолчанию она удаляется при его завершении.'),
        ('explanation', 'Допишите запрос, чтобы узнать размер базы данных appdb:
```
SELECT pg_size_pretty(___(''appdb''));
```', NULL, NULL, 'В практике курса так проверяют, насколько выросла база после создания таблиц.', 'pg_database_size(''appdb'') возвращает размер базы в байтах, а pg_size_pretty форматирует его для чтения.'),
        ('explanation', 'Таблица t есть в схемах app и public, доступ к обеим схемам есть, временной таблицы t нет, search_path = app, public. Из какой схемы возьмётся t в запросе SELECT * FROM t?', NULL, NULL, 'Можно провести аналогию с переменной PATH в операционной системе.', 'При search_path = app, public имя t сначала ищется в app; поскольку таблица там есть, public уже не используется.'),
        ('explanation', 'Допишите команду psql, чтобы видеть запросы к системному каталогу, которые выполняют команды вроде \d+:
```
\set ___ on
```', NULL, NULL, 'В практике курса так выясняют, какие запросы выполняет команда \d+ pg_views.', 'ECHO_HIDDEN = on показывает SQL, который psql выполняет для служебных метакоманд.'),
        ('explanation', 'Как правильно изменять содержимое системного каталога?', NULL, NULL, 'Читать каталог можно обычными запросами SELECT.', 'Описание объектов меняют командами CREATE, ALTER и DROP: сервер сам согласованно обновляет нужные каталоги и зависимости.'),
        ('explanation', 'Что выводит команда psql \d pg_class?', NULL, NULL, 'С модификатором + выводится подробное описание.', '\d pg_class показывает структуру отношения pg_class, в том числе столбцы, типы и индексы, а не его строки.'),
        ('explanation', 'Почему не рекомендуется создавать собственные объекты с именами на pg_?', NULL, NULL, 'Столбцы таблиц каталога имеют свой трёхбуквенный префикс.', 'Префикс pg_ используется системными объектами; собственное такое имя может конфликтовать с текущим или будущим объектом каталога.'),
        ('explanation', 'Что верно для системного каталога?', NULL, NULL, 'Основная схема каталога — pg_catalog, альтернативное представление — information_schema.', 'Каталог хранит метаданные в таблицах самого кластера; к ним и представлениям над ними можно обращаться обычным SELECT.'),
        ('explanation', 'Допишите запрос, чтобы по oid 1259 получить имя соответствующей таблицы:
```
SELECT 1259::___;
```', NULL, NULL, 'Обратное преобразование: ''pg_class''::regclass::oid.', 'Приведение 1259::regclass интерпретирует число как OID отношения и выводит его имя — pg_class.'),
        ('explanation', 'Допишите команду из практики курса, чтобы шаблон template1 хранился в табличном пространстве ts:
```
ALTER DATABASE template1 SET ___ ts;
```', NULL, NULL, 'Пока к перемещаемой базе есть подключения, команда не выполнится.', 'ALTER DATABASE template1 SET TABLESPACE ts переносит объекты из прежнего пространства по умолчанию в ts. Команду выполняют из другой базы; подключений к template1 быть не должно.'),
        ('explanation', 'Почему внутри PGDATA/global нет подкаталогов баз данных?', NULL, NULL, 'В PGDATA/base данные, наоборот, разложены по подкаталогам баз.', 'В global находятся общие объекты кластера, поэтому они не распределяются по каталогам отдельных баз.'),
        ('explanation', 'Что будет, если для табличного пространства уменьшить random_page_cost относительно seq_page_cost?', NULL, NULL, 'В практике курса для pg_default задают random_page_cost = 1.1.', 'Уменьшение random_page_cost относительно seq_page_cost делает планы с произвольным доступом, часто индексные, дешевле в оценке планировщика.'),
        ('explanation', 'Допишите команду, чтобы табличное пространство ts стало пространством по умолчанию для новой базы appdb:
```
CREATE DATABASE appdb ___ ts;
```', NULL, NULL, 'Без указания база получает табличное пространство шаблона.', 'Предложение TABLESPACE ts назначает ts пространством по умолчанию для новой базы appdb.'),
        ('explanation', 'Как называется первый файл основного слоя постоянной таблицы?', NULL, NULL, 'Основной слой содержит сами данные: версии строк или индексные записи.', 'Первый файл основного слоя постоянного отношения называется по его filenode без суффикса слоя; следующие сегменты имеют .1, .2 и далее.'),
        ('explanation', 'Как называется второй файл-сегмент основного слоя, если первый называется NNN?', NULL, NULL, 'Новый сегмент создаётся, когда файл дорастает до 1 ГБ.', 'Первый сегмент имеет имя NNN, второй — NNN.1, третий — NNN.2.'),
        ('explanation', 'Строка с длинным значением обновляется, но само длинное значение не меняется. Что происходит в toast-таблице?', NULL, NULL, 'Toast-таблица читается только при обращении к длинному значению.', 'Если вынесенное значение не меняется, новая версия строки сохраняет ссылку на прежнее TOAST-значение без повторного копирования.'),
        ('explanation', 'Какая стратегия хранения по умолчанию используется для столбца типа text?', NULL, NULL, 'Стратегию меняет команда ALTER TABLE … ALTER COLUMN … SET STORAGE.', 'Для text по умолчанию используется EXTENDED: допускаются сжатие и вынос длинных значений в TOAST.'),
        ('explanation', 'Допишите команду, задающую lz4 как метод сжатия TOAST по умолчанию в сеансе:
```
SET default_toast_compression = ___;
```', NULL, NULL, 'Метод, заданный для отдельного столбца (COMPRESSION), имеет приоритет над значением по умолчанию.', 'Значение ''lz4'' задаёт метод сжатия TOAST по умолчанию для сеанса, если сборка его поддерживает. Явно заданный метод COMPRESSION отдельного столбца имеет приоритет.'),
        ('explanation', 'Что показывает pg_relation_size(''t''), вызванная с одним параметром?', NULL, NULL, 'Размер любого слоя можно получить, указав его имя вторым параметром.', 'При одном аргументе pg_relation_size возвращает размер основного слоя main, без TOAST и отдельных индексов.'),
        ('explanation', 'В какой схеме лежит toast-таблица временной таблицы?', NULL, NULL, 'Обычно toast-таблицы не видны, поскольку лежат в отдельных схемах.', 'TOAST-таблица временной таблицы находится во временной TOAST-схеме pg_toast_temp_N соответствующего сеанса.'),
        ('explanation', 'Как часто обслуживающий процесс записывает собранную статистику в разделяемую память?', NULL, NULL, 'Поэтому статистика, которую видит процесс, немного запаздывает.', 'Backend обычно передаёт накопленную статистику в общую память не чаще раза в секунду; частота задаётся константой сборки.'),
        ('explanation', 'Где сохраняется накопительная статистика при штатной остановке сервера?', NULL, NULL, 'При аварийной остановке счётчики сбрасываются.', 'При штатной остановке накопительная статистика сохраняется в PGDATA/pg_stat и восстанавливается при следующем штатном запуске.'),
        ('explanation', 'Как сбросить закешированную в процессе статистику раньше конца транзакции?', NULL, NULL, 'Иначе кеш сбрасывается в конце транзакции.', 'pg_stat_clear_snapshot() сбрасывает кеш статистики текущего процесса, чтобы следующее обращение прочитало её заново.'),
        ('explanation', 'Какое представление позволяет следить за ходом VACUUM FULL?', NULL, NULL, 'Есть также представления для создания базовой резервной копии и COPY.', 'VACUUM FULL переписывает таблицу, поэтому его ход, как и CLUSTER, виден в pg_stat_progress_cluster.'),
        ('explanation', 'Что верно для коллектора сообщений?', NULL, NULL, 'Коллектор собирает сообщения со всех процессов сервера.', 'Коллектор рассчитан на сохранение сообщений; если он не успевает их обрабатывать, отправляющие процессы могут ждать.'),
        ('explanation', 'Сколько файлов журнала сообщений получится при log_filename = ''postgresql-%a.log'', ротации раз в сутки и log_truncate_on_rotation = on?', NULL, NULL, 'Комбинируя маску и время ротации, получают разные схемы хранения.', '%a задаёт день недели: имена повторяются каждые семь дней, а ротация с усечением переиспользует эти семь файлов.'),
        ('explanation', 'Что делает параметр log_truncate_on_rotation = on?', NULL, NULL, 'Альтернатива встроенной ротации — системная утилита logrotate.', 'При ротации по времени существующий файл с нужным именем усекается, если log_truncate_on_rotation включён; иначе запись продолжается в конец.'),
        ('explanation', 'Какой параметр записывает в журнал сообщения о контрольных точках?', NULL, NULL, 'По умолчанию почти весь остальной вывод в журнал отключён.', 'log_checkpoints включает сообщения о контрольных точках; в PostgreSQL 16 он включён по умолчанию.'),
        ('explanation', 'Какой параметр записывает в журнал долгие ожидания блокировок?', NULL, NULL, 'Взаимоблокировки записываются в журнал и без этого параметра.', 'log_lock_waits журналирует ожидания блокировок, превысившие deadlock_timeout; взаимоблокировка для этого не обязательна.'),
        ('explanation', 'Какое ограничение есть у анализатора журналов pgBadger?', NULL, NULL, 'pgBadger — стандарт де-факто для анализа журнала.', 'pgBadger требует совместимого формата журнала и сообщений на английском; настройки журнала готовят согласно его документации.'),
        ('explanation', 'Можно ли средствами PostgreSQL ограничить роли объём занимаемого на диске места?', NULL, NULL, 'Место на диске смотрят и из базы, и из ОС (du, df).', 'В PostgreSQL 16 нет встроенной дисковой квоты на роль; квота ОС относится к пользователю серверного процесса, а не к SQL-ролям по отдельности.'),
        ('explanation', 'Допишите маску имени файла, чтобы при ротации раз в час и log_truncate_on_rotation = on получалось 24 файла в сутки:
```
log_filename = ''postgresql-___.log''
```', NULL, NULL, 'Время ротации задаёт параметр log_rotation_age.', '%H подставляет час суток от 00 до 23, давая 24 повторяющихся имени при почасовой ротации.'),
        ('explanation', 'Какой атрибут нужен роли, чтобы создавать другие роли?', NULL, NULL, 'Атрибуты задают общие особенности роли, не связанные с конкретными объектами. Суперпользователь может всё и без них.', 'Атрибут CREATEROLE разрешает создавать роли в пределах установленных ограничений; LOGIN и CREATEDB дают другие возможности.'),
        ('explanation', 'Как следует располагать записи в pg_hba.conf?', NULL, NULL, 'Если не подошла ни одна запись, доступ запрещается.', 'В pg_hba.conf действует первая подходящая запись, поэтому частные исключения размещают перед общими правилами.'),
        ('explanation', 'Где в кластере хранится хеш пароля роли?', NULL, NULL, 'Если для роли пароль не задан, а в pg_hba.conf указан парольный метод, в доступе будет отказано.', 'Хеш пароля хранится в поле rolpassword общего каталога pg_authid, доступ к которому ограничен.'),
        ('explanation', 'Какая привилегия нужна, чтобы роль могла создавать временные таблицы в базе данных?', NULL, NULL, 'Привилегия CREATE на базу данных разрешает создавать в ней схемы.', 'Привилегия TEMPORARY на базу разрешает создавать в ней временные таблицы независимо от права CREATE в public.'),
        ('explanation', 'Роль bob с атрибутом NOINHERIT включили в роль dba командой GRANT dba TO bob. Как bob может воспользоваться привилегиями dba?', NULL, NULL, 'В PostgreSQL 16 атрибут NOINHERIT задаёт значение по умолчанию для параметра INHERIT новых членств; по умолчанию роль наследует привилегии включающей роли.', 'Такое членство не наследует права dba автоматически, но по умолчанию разрешает SET ROLE; bob может выполнить SET ROLE dba.'),
        ('explanation', 'Почему недостаточно один раз отозвать у public привилегию EXECUTE на все подпрограммы?', NULL, NULL, 'Для этого служит команда ALTER DEFAULT PRIVILEGES.', 'Отзыв прав у существующих подпрограмм не меняет стандартные права новых: для запрета EXECUTE у PUBLIC на будущие объекты меняют default privileges.'),
        ('explanation', 'Что проверяется после того, как в pg_hba.conf найдена подходящая запись?', NULL, NULL, 'После найденной записи другие строки файла уже не рассматриваются.', 'Для обычного подключения нужны успешная аутентификация, LOGIN у роли и CONNECT на целевую базу; права таблиц проверяются позже.'),
        ('explanation', 'Какие привилегии определены для последовательностей?', NULL, NULL, 'Выбирая привилегии, можно разрешить или запретить доступ к управляющим функциям последовательности.', 'Для последовательности SELECT разрешает currval, USAGE — currval и nextval, UPDATE — nextval и setval.'),
        ('explanation', 'Какие из перечисленных ролей входят в число предопределённых в PostgreSQL 16?', NULL, NULL, 'Список ролей, включая предопределённые, показывает команда psql \duS.', 'В PostgreSQL 16 предопределены pg_monitor для мониторинга и pg_write_all_data для записи данных; pg_admin и pg_superuser не предопределены.'),
        ('explanation', 'Допишите строку pg_hba.conf, чтобы метод peer использовал отображение имён stmap из pg_ident.conf:
```
# TYPE  DATABASE  USER       METHOD
local   all       alice,bob  peer ___
```', NULL, NULL, 'Отображение связывает имя пользователя ОС с именем роли в базе данных; одно отображение можно использовать для разных ролей.', 'Опция map=stmap указывает методу peer использовать отображение stmap из pg_ident.conf.'),
        ('explanation', 'На какой момент можно восстановить данные из обычной логической копии?', NULL, NULL, 'Это один из недостатков логической копии наряду с невысокой скоростью.', 'Логический дамп отражает свой снимок данных и не содержит WAL для продвижения к более позднему состоянию.'),
        ('explanation', 'Что позволяет ускорить копирование и восстановление большой базы данных утилитами pg_dump и pg_restore?', NULL, NULL, 'При восстановлении pg_restore позволяет также ограничить набор объектов.', 'Параллельный pg_dump требует directory; pg_restore поддерживает параллельное восстановление архивов directory и custom.'),
        ('explanation', 'Что делает pg_basebackup в самом начале работы?', NULL, NULL, 'Подключение выполняется по протоколу репликации.', 'В начале базового копирования выполняется контрольная точка, задающая исходную позицию WAL для согласованного восстановления копии.'),
        ('explanation', 'Чем потоковый архив журналов, который ведёт pg_receivewal, отличается от файлового?', NULL, NULL, 'Утилиту нужно запускать и перезапускать средствами операционной системы.', 'pg_receivewal принимает WAL по мере появления и пишет текущий сегмент, не ожидая его завершения для передачи в архив.'),
        ('explanation', 'Какой суффикс имеет файл незаполненного сегмента, который сейчас пишет pg_receivewal?', NULL, NULL, 'При восстановлении вместе с обычными сегментами можно использовать и недозаписанный файл.', 'Текущий незавершённый сегмент pg_receivewal имеет суффикс .partial; после завершения сегмента он переименовывается.'),
        ('explanation', 'Что нужно подготовить заранее, чтобы восстановить базу данных из копии pg_dump, сделанной без ключа --create, на новом кластере?', NULL, NULL, 'После восстановления имеет смысл выполнить ANALYZE, чтобы собрать статистику.', 'Дамп без --create восстанавливают в заранее созданную пустую базу из template0; также подготавливают используемые роли и табличные пространства. После восстановления рекомендуется ANALYZE, поскольку дамп не содержит статистики планировщика.'),
        ('explanation', 'Что верно для физической резервной копии?', NULL, NULL, 'Для физической копии используют утилиту pg_basebackup.', 'Физическая копия содержит готовые файлы, поэтому не требует построения объектов заново; непрерывный WAL позволяет довести её до выбранной точки.'),
        ('explanation', 'Допишите команду archive_command, чтобы сегмент копировался в архив под своим именем:
```
archive_command = ''cp %p /mnt/archive/___''
```', NULL, NULL, 'Если команда завершается с нулевым статусом, сегмент считается заархивированным.', '%f подставляет имя архивируемого файла без каталога, поэтому получается путь /mnt/archive/имя_файла.'),
        ('explanation', 'Почему при wal_level = minimal физическая репликация невозможна?', NULL, NULL, 'Начиная с версии 10 по умолчанию используется уровень replica.', 'На minimal некоторые изменения новых или переписанных отношений могут не журналироваться полностью, поэтому WAL недостаточно для физической реплики.'),
        ('explanation', 'Как настраивают реплику для долгих аналитических запросов?', NULL, NULL, 'Альтернатива для коротких OLTP-запросов — обратная связь реплики с основным сервером.', 'Увеличение допустимой задержки применения конфликтующего WAL даёт долгому запросу закончиться ценой отставания реплики.'),
        ('explanation', 'Гарантируется ли согласованность данных, если приложение читает то с основного сервера, то с реплик?', NULL, NULL, 'Для автоматического распределения запросов нужны внешние средства, например балансировщики.', 'Разные серверы могут находиться на разных позициях применения WAL; обычное синхронное подтверждение не делает произвольные чтения между серверами единым снимком.'),
        ('explanation', 'От каких реплик каскада основной сервер получает обратную связь hot_standby_feedback, если она включена?', NULL, NULL, 'Чем дальше реплика от основного сервера, тем больше запаздывание.', 'При включённой обратной связи промежуточные реплики передают сведения вверх по цепочке до основного сервера.'),
        ('explanation', 'Из чего создают физическую реплику?', NULL, NULL, 'Реплика постоянно применяет журнальные записи, пришедшие с основного сервера.', 'Физическую реплику создают из физической копии основного кластера, чтобы файлы и идентификатор системы соответствовали его WAL.'),
        ('explanation', 'Что делает реплика с настроенным чтением из архива (restore_command), если очередную журнальную запись не удаётся получить по протоколу репликации?', NULL, NULL, 'Для файловой репликации нужно настроенное непрерывное архивирование.', 'При невозможности продолжить поток реплика повторяет поиск WAL в настроенном архиве, локальном pg_wal и через потоковое подключение.'),
        ('explanation', 'Какой параметр ограничивает число одновременных подключений по протоколу репликации?', NULL, NULL, 'Настройки по умолчанию достаточны для локального подключения.', 'max_wal_senders ограничивает одновременное число процессов отправки WAL, используемых репликацией и базовым копированием.'),
        ('explanation', 'Что нужно, чтобы запросы распределялись между репликами автоматически?', NULL, NULL, 'Распределение нагрузки по чтению — одна из типичных задач реплик.', 'Физическая репликация не направляет клиентские запросы между узлами; для этого настраивают приложение, прокси или балансировщик.'),
        ('explanation', 'Какие два источника журнальных записей могут конфликтовать с запросом на реплике?', NULL, NULL, 'Поэтому такую реплику настраивают, чтобы она откладывала применение конфликтующих записей.', 'На реплике запрос может конфликтовать с воспроизводимой ACCESS EXCLUSIVE или с удалением версий строк, ещё нужных его снимку.'),
        ('explanation', 'Для решения каких задач применяют физическую репликацию?', NULL, NULL, 'Физическая репликация создаёт точную копию всего кластера.', 'Горячие реплики выполняют чтение, позволяя вынести аналитику и распределить запросы между несколькими серверами.'),
        ('explanation', 'Допишите строку pg_hba.conf на основном сервере, чтобы разрешить роли repl подключения физической репликации:
```
# TYPE  DATABASE  USER  ADDRESS      METHOD
host    ___       repl  10.0.0.0/24  scram-sha-256
```', NULL, NULL, 'Роли для такого подключения нужен атрибут REPLICATION или права суперпользователя.', 'Значение replication в поле DATABASE соответствует подключениям физической репликации; all их не включает. Подключающаяся роль должна иметь атрибут REPLICATION либо быть суперпользователем.'),
        ('explanation', 'Как избежать конфликтов уникальных ключей из-за того, что значения последовательностей не реплицируются?', NULL, NULL, 'Автоматического разрешения конфликтов в PostgreSQL нет.', 'Непересекающиеся диапазоны генерации ключей или подходящие UUID уменьшают риск одинаковых ключей при независимой записи на узлах.'),
        ('explanation', 'Таблица orders ссылается внешним ключом на customers, на подписчике ключ тоже есть. Что нужно для правильной репликации команды TRUNCATE customers CASCADE?', NULL, NULL, 'Публикация обрабатывает команды INSERT, UPDATE, DELETE и TRUNCATE.', 'Все таблицы, которые затронет TRUNCATE CASCADE, должны реплицироваться одной подпиской, иначе внешние ключи на подписчике могут помешать операции.'),
        ('explanation', 'Может ли подписчик получать изменения не напрямую с публикующего сервера, а с его физической реплики?', NULL, NULL, 'Подписчик получает изменения по протоколу репликации.', 'PostgreSQL 16 поддерживает логическое декодирование на физической реплике; её walsender может передавать изменения логическому подписчику при нужных настройках.'),
        ('explanation', 'Обеспечивает ли схема мастер-мастер на логической репликации глобальные распределённые транзакции?', NULL, NULL, 'Двунаправленная репликация появилась в PostgreSQL 16.', 'Двунаправленная логическая репликация не координирует фиксацию одной глобальной транзакции на всех узлах; конфликты и согласование остаются задачей приложения.'),
        ('explanation', 'Что дополнительно попадает в журнал при wal_level = logical?', NULL, NULL, 'Поскольку по умолчанию используется replica, для логической репликации значение надо менять.', 'Уровень logical добавляет сведения для восстановления изменений строк и их идентификации при логическом декодировании, включая необходимую информацию о каталогах.'),
        ('explanation', 'Допишите команду, чтобы публиковать только вставки строк с положительным балансом:
```
CREATE PUBLICATION pub FOR TABLE accounts ___ (balance > 0)
    WITH (publish = ''insert'');
```', NULL, NULL, 'Для UPDATE и DELETE столбцы фильтра должны входить в REPLICA IDENTITY. Можно также указать набор столбцов таблицы.', 'WHERE (balance > 0) задаёт фильтр строк. Для публикации только INSERT фильтр может использовать любой столбец; при публикации UPDATE или DELETE его столбцы должны входить в REPLICA IDENTITY.'),
        ('explanation', 'Допишите команду, чтобы добавить таблицу orders в существующую публикацию, сохранив уже опубликованные таблицы:
```
ALTER PUBLICATION pub ___ TABLE orders;
```', NULL, NULL, 'Подписчик получает изменения добавленной таблицы после обновления подписки.', 'ADD TABLE orders добавляет таблицу, сохраняя прежний состав публикации; SET TABLE заменяет список. Чтобы существующая подписка подхватила добавленную таблицу, на подписчике выполняют ALTER SUBSCRIPTION имя REFRESH PUBLICATION.'),
        ('explanation', 'Допишите параметр подписки, чтобы при двунаправленной репликации не пересылать обратно изменения, полученные от другого узла:
```
CREATE SUBSCRIPTION sub
    CONNECTION ''host=srv2 dbname=appdb''
    PUBLICATION pub
    WITH (copy_data = false, ___ = none);
```', NULL, NULL, 'Начальную синхронизацию в такой схеме отключают параметром copy_data = false.', 'origin = none запрашивает только изменения без происхождения от другого узла репликации, предотвращая их пересылку обратно.'),
        ('explanation', 'Чем физическая резервная копия отличается от логической (дампа)?', NULL, NULL, 'Дамп делают pg_dump и pg_dumpall, физическую копию — pg_basebackup или низкоуровневым копированием.', 'Физическая копия сохраняет файлы кластера, логическая — определения объектов и данные для их воссоздания средствами SQL.'),
        ('explanation', 'Нужно перенести одну базу на сервер с другой основной версией PostgreSQL. Что подходит?', NULL, NULL, 'Для обновления основной версии используют также pg_upgrade и логическую репликацию.', 'pg_dump выгружает одну базу на логическом уровне, поэтому её можно перенести на совместимую другую основную версию без копирования физических файлов.'),
        ('explanation', 'Мешает ли работающий pg_dump другим сеансам?', NULL, NULL, 'Дамп отражает состояние базы на момент начала выгрузки, так как читается один снимок данных.', 'pg_dump удерживает ACCESS SHARE: обычные чтение и запись продолжаются, а операции, требующие ACCESS EXCLUSIVE на выгружаемых таблицах, ждут.'),
        ('explanation', 'Как в PostgreSQL 16 называется функция начала низкоуровневого резервного копирования (раньше pg_start_backup)?', NULL, NULL, 'Завершает копирование функция pg_backup_stop.', 'В PostgreSQL 16 низкоуровневое копирование начинает pg_backup_start; прежнее имя pg_start_backup изменено в версии 15.'),
        ('explanation', 'Что делает в PostgreSQL команда ALTER DATABASE … BEGIN BACKUP?', NULL, NULL, 'Копирование выполняется для всего кластера, а не для отдельной базы.', 'В PostgreSQL нет ALTER DATABASE ... BEGIN BACKUP; низкоуровневое копирование начинают через pg_backup_start.'),
        ('explanation', 'Что важно при низкоуровневом копировании через pg_backup_start в PostgreSQL 16?', NULL, NULL, 'pg_backup_stop возвращает содержимое файла backup_label, его нужно сохранить вместе с копией.', 'Сеанс сохраняют от pg_backup_start до pg_backup_stop; разрыв соединения отменяет режим копирования. Возвращённые pg_backup_stop содержимое backup_label и непустой tablespace_map сохраняют без изменений в корне резервной копии.'),
        ('explanation', 'Допишите вызов, чтобы копирование началось сразу, с немедленной контрольной точкой:
```
SELECT pg_backup_start(label => ''nightly'', fast => ___);
```', NULL, NULL, 'Немедленная контрольная точка создаёт всплеск записи на диск.', 'fast => true требует немедленной контрольной точки; false допускает растянутую запись перед началом копирования.'),
        ('explanation', 'Что нужно для восстановления кластера на момент в прошлом (PITR)?', NULL, NULL, 'Целевая точка задаётся параметрами recovery_target_*.', 'Для PITR нужна подходящая базовая копия и непрерывная цепочка WAL от её начальной позиции до цели восстановления.'),
        ('explanation', 'Допишите параметр, чтобы восстановить кластер на состояние 14:30 10 октября:
```
___ = ''2026-10-10 14:30:00+03''
```', NULL, NULL, 'Есть также recovery_target_xid, recovery_target_lsn и recovery_target_name.', 'recovery_target_time задаёт время, до которого нужно воспроизвести WAL при восстановлении.'),
        ('explanation', 'Что по умолчанию делает сервер, достигнув целевой точки восстановления?', NULL, NULL, 'Продолжить работу после проверки можно функцией pg_wal_replay_resume().', 'По умолчанию recovery_target_action = pause приостанавливает восстановление на цели. После проверки pg_wal_replay_resume() завершает восстановление. Без hot_standby значение pause действует как shutdown.'),
        ('explanation', 'Можно ли восстановиться из базовой копии на момент раньше окончания её создания?', NULL, NULL, 'Поэтому базовые копии делают регулярно и хранят несколько.', 'Горячая копия становится согласованной лишь после воспроизведения необходимого WAL до конца копирования; для более ранней цели нужна более ранняя копия.'),
        ('explanation', 'Допишите запрос, чтобы посчитать долю попаданий в буферный кеш (buffer hit ratio) по базам:
```
SELECT datname,
       round(100.0 * blks_hit / nullif(blks_hit + ___, 0), 2) AS hit_ratio
FROM pg_stat_database;
```', NULL, NULL, 'Для OLTP обычно ожидают долю около 99%.', 'Всего обращений к блокам — blks_hit + blks_read; доля попаданий равна blks_hit, делённому на эту сумму.'),
        ('explanation', 'Чем опасны сеансы в состоянии idle in transaction?', NULL, NULL, 'Найти их можно в pg_stat_activity по state.', 'Idle in transaction сохраняет открытую транзакцию: её блокировки и старый снимок или XID могут мешать другим сеансам и очистке.'),
        ('explanation', 'Какие системы используют для мониторинга PostgreSQL?', NULL, NULL, 'В курсе упоминаются также PoWA и pg_profile; журнал анализируют pgBadger.', 'Zabbix может собирать метрики PostgreSQL по шаблонам, а Prometheus получает их через postgres_exporter.'),
        ('explanation', 'Какая функция показывает, какие процессы блокируют данный процесс?', NULL, NULL, 'Сами блокировки видны в представлении pg_locks.', 'pg_blocking_pids(pid) возвращает массив PID процессов, препятствующих получению блокировки указанным процессом.'),
        ('explanation', 'Какое значение synchronous_commit гарантирует, что после фиксации изменения уже видны запросам на синхронной реплике?', NULL, NULL, 'Чем строже режим, тем медленнее фиксация.', 'remote_apply ждёт применения WAL синхронной репликой, поэтому последующий новый снимок на ней уже может видеть подтверждённые изменения.'),
        ('explanation', 'Что гарантирует synchronous_commit = remote_write при синхронной реплике?', NULL, NULL, 'Режим быстрее on, но немного менее надёжен.', 'remote_write ждёт записи WAL в файловую систему реплики, но не обязательного сброса на её устойчивый носитель.'),
        ('explanation', 'Какие значения synchronous_commit заставляют фиксацию ждать синхронную реплику?', NULL, NULL, 'При пустом synchronous_standby_names реплику не ждёт ни одно значение.', 'При настроенной синхронной репликации remote_write ждёт записи WAL в ОС реплики, on — сброса на носитель, remote_apply — применения. При пустом synchronous_standby_names ни один режим не ждёт реплику.'),
        ('explanation', 'Допишите команду, чтобы не ждать записи журнала только для текущей транзакции:
```
BEGIN;
SET ___ synchronous_commit = off;
```', NULL, NULL, 'Так ускоряют некритичные транзакции, не меняя настройку для всех.', 'SET LOCAL ограничивает synchronous_commit = off текущей транзакцией; после её завершения возвращается настройка сеанса.'),
        ('explanation', 'Что верно для свойств ACID?', NULL, NULL, 'Согласованность означает переход базы из одного корректного состояния в другое.', 'Стойкость означает сохранение подтверждённых изменений после сбоя, а атомарность — применение изменений транзакции целиком либо их отмену целиком.'),
        ('explanation', 'Что будет с таблицей, созданной внутри транзакции, если выполнить ROLLBACK?', NULL, NULL, 'Исключения есть, например CREATE DATABASE.', 'CREATE TABLE транзакционна: при ROLLBACK отменяются и создание таблицы, и выполненные в ней изменения.'),
        ('explanation', 'Какую команду нельзя выполнить внутри блока транзакции?', NULL, NULL, 'Вне явного блока транзакции выполняются также VACUUM и CREATE INDEX CONCURRENTLY.', 'CREATE DATABASE запрещена внутри явного блока транзакции; для перечисленных обычных форм CREATE TABLE, ALTER TABLE и TRUNCATE такого общего запрета нет.'),
        ('explanation', 'Что нужно учитывать, запуская VACUUM FULL для большой таблицы?', NULL, NULL, 'Без долгой блокировки таблицы место возвращает расширение pg_repack.', 'VACUUM FULL держит ACCESS EXCLUSIVE и создаёт новую копию таблицы с индексами, поэтому нужны время недоступности и дополнительное место.'),
        ('explanation', 'Чем общий план подготовленного оператора отличается от частного?', NULL, NULL, 'Режимом управляет параметр plan_cache_mode.', 'Частный план учитывает конкретные значения параметров; общий план не зависит от этих значений и может использоваться повторно.'),
        ('explanation', 'Когда при plan_cache_mode = auto подготовленный оператор с параметрами переходит на общий план?', NULL, NULL, 'Если общий план выбран неудачно, помогает force_custom_plan.', 'При auto сначала выполняются пять частных планов; затем стоимость общего плана сравнивается со средней стоимостью частных с учётом затрат планирования.'),
        ('explanation', 'Допишите команду, чтобы подготовленные операторы с параметрами всегда строили частный план:
```
SET plan_cache_mode = ___;
```', NULL, NULL, 'Параметр можно задать для сеанса, роли или функции.', 'force_custom_plan требует строить частный план с учётом текущих значений параметров при каждом выполнении подготовленного оператора.'),
        ('explanation', 'Как в штатном режиме обновляется статистика для планировщика?', NULL, NULL, 'Статистика хранится в pg_statistic, удобно смотреть её в pg_stats.', 'Автоочистка запускает ANALYZE, когда число изменений таблицы превышает порог, зависящий от threshold и scale_factor.'),
        ('explanation', 'Зачем нужна команда CREATE STATISTICS?', NULL, NULL, 'Расширенную статистику собирает ANALYZE, без него она пуста.', 'CREATE STATISTICS объявляет объект расширенной статистики, например для зависимости значений нескольких столбцов; данные для него затем собирает ANALYZE.'),
        ('explanation', 'Допишите команду, чтобы после ANALYZE планировщик учитывал зависимость почтового индекса от города:
```
CREATE STATISTICS addr_stats (___) ON city, zip FROM addresses;
```', NULL, NULL, 'Есть также вид mcv — частые сочетания значений.', 'Вид dependencies собирает сведения о функциональных зависимостях столбцов, чтобы планировщик не считал связанные условия независимыми.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
